    /// <summary>True when <paramref name="line"/> is the per-locale version/effective-date preamble.</summary>
    public static bool IsVersionPreambleLine(string line)
    {
        line = line.Trim();
        if (line.Length == 0 || line.Length > 120)
            return false;

        return line.Contains(EffectiveDate, StringComparison.Ordinal)
            && line.Contains(Version.ToString(), StringComparison.Ordinal);
    }

